import time
from functools import wraps

def retry_once(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except Exception:
            time.sleep(1)
            return func(*args, **kwargs)
    return wrapper

@retry_once
def fetch_with_retry(quote, start, end):
    return quote.history(start=start, end=end)
